create extension if not exists pgcrypto;
create table if not exists schools (id uuid primary key default gen_random_uuid(), name text not null, plan text default 'pilot', created_at timestamptz default now());
create table if not exists profiles (id uuid primary key, school_id uuid references schools(id) on delete cascade, role text not null check (role in ('student','teacher','admin','parent')), full_name text not null, grade text, created_at timestamptz default now());
create table if not exists classes (id uuid primary key default gen_random_uuid(), school_id uuid references schools(id) on delete cascade, teacher_id uuid references profiles(id), name text not null, grade text, class_code text unique not null, created_at timestamptz default now());
create table if not exists class_enrollments (class_id uuid references classes(id) on delete cascade, student_id uuid references profiles(id) on delete cascade, joined_at timestamptz default now(), primary key(class_id,student_id));
create table if not exists skills (id uuid primary key default gen_random_uuid(), subject text not null, grade text not null, domain text, name text not null, standard_code text, created_at timestamptz default now());
create table if not exists questions (id uuid primary key default gen_random_uuid(), skill_id uuid references skills(id) on delete set null, school_id uuid references schools(id) on delete cascade, author_id uuid references profiles(id), prompt text not null, options jsonb not null, correct_index integer not null, hint text, explanation text, difficulty text default 'on_level', created_at timestamptz default now());
create table if not exists assignments (id uuid primary key default gen_random_uuid(), class_id uuid references classes(id) on delete cascade, creator_id uuid references profiles(id), skill_id uuid references skills(id), title text not null, due_at timestamptz, publish_at timestamptz, question_count integer default 20 check (question_count between 1 and 20), seconds_per_question integer default 180, status text default 'assigned', created_at timestamptz default now());
create table if not exists assignment_questions (assignment_id uuid references assignments(id) on delete cascade, question_id uuid references questions(id) on delete cascade, position integer not null, primary key(assignment_id,question_id));
create table if not exists attempts (id uuid primary key default gen_random_uuid(), assignment_id uuid references assignments(id) on delete cascade, student_id uuid references profiles(id) on delete cascade, status text default 'draft', auto_score integer default 0, teacher_score integer, feedback text, submitted_at timestamptz, graded_at timestamptz, graded_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists attempt_answers (id uuid primary key default gen_random_uuid(), attempt_id uuid references attempts(id) on delete cascade, question_id uuid references questions(id), selected_index integer, work_image_url text, time_used_seconds integer, created_at timestamptz default now());
create table if not exists goals (id uuid primary key default gen_random_uuid(), student_id uuid references profiles(id) on delete cascade, title text not null, target integer not null, progress integer default 0, due_at date, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists portfolio_items (id uuid primary key default gen_random_uuid(), student_id uuid references profiles(id) on delete cascade, title text not null, subject text, item_type text, description text, artifact_url text, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists notifications (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, title text not null, message text not null, is_read boolean default false, created_by uuid references profiles(id), created_at timestamptz default now());
create table if not exists ai_activity (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, prompt text not null, response text not null, created_at timestamptz default now());
alter table schools enable row level security;
alter table profiles enable row level security;
alter table classes enable row level security;
alter table class_enrollments enable row level security;
alter table assignments enable row level security;
alter table attempts enable row level security;
alter table attempt_answers enable row level security;
